import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-sidebar',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './sidebar.component.html',
  styleUrl: './sidebar.component.css'
})
export class SidebarComponent {
  menuItems = [
    { label: 'Inicio', icon: '🏠', active: false },
    { label: 'Reuniones', icon: '📅', active: true },
    { label: 'Calendario', icon: '📆', active: false },
    { label: 'Historial', icon: '📋', active: false },
    { label: 'Contactos', icon: '👥', active: false },
    { label: 'Configuración', icon: '⚙️', active: false }
  ];
}
<nav class="sidebar">
  <div class="sidebar-header">
    <h1 class="logo">MeetFloow</h1>
  </div>
  <ul class="sidebar-menu">
    <li *ngFor="let item of menuItems" [class.active]="item.active">
      <span class="icon">{{ item.icon }}</span>
      <span class="label">{{ item.label }}</span>
    </li>
  </ul>
</nav>
